  useEffect(() => { setPage(1); }, [filter, exceptionId]);
  useEffect(() => {
    if (selectedAssumption && preview) document.getElementById(`hipotese-${selectedAssumption}`)?.scrollIntoView({ block: 'nearest' });
  }, [selectedAssumption, preview]);
